<?php
namespace App\Filament\Admin\Resources\PolicyIssuances\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\PolicyIssuances\PolicyIssuanceResource;use Filament\Actions\Action;use Filament\Forms\Components\{TextInput,Textarea};use Filament\Resources\Pages\ViewRecord;final class ViewPolicyIssuance extends ViewRecord{protected static string $resource=PolicyIssuanceResource::class;protected function getHeaderActions():array{return[Action::make('approve')->label('Authorize & issue')->icon('heroicon-o-shield-check')->color('success')->visible(fn()=>in_array($this->record->status,['REQUESTED','CARRIER_REVIEW'],true))->schema([TextInput::make('policy_number')->required()->maxLength(100),TextInput::make('carrier_reference')->required()->maxLength(160),TextInput::make('previous_policy_id')->uuid()])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyIssuanceService::class)->approve($this->record,$d,auth()->user()))===null)return;}),Action::make('reject')->icon('heroicon-o-x-circle')->color('danger')->visible(fn()=>in_array($this->record->status,['REQUESTED','CARRIER_REVIEW'],true))->schema([Textarea::make('reason')->required()->minLength(20)->maxLength(2000)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyIssuanceService::class)->reject($this->record,$d['reason'],auth()->user()))===null)return;})];}}
